export function locale() { return current; }
export function t(key) { return messages[current]?.[key] || messages.en[key] || key; }
export function formatMoney(minor, currency) {
  if (!Number.isSafeInteger(minor) || minor < 0) throw new RangeError('minor must be a non-negative safe integer');
  const formatter = new Intl.NumberFormat(current, { style: 'currency', currency });
  const scale = 10 ** formatter.resolvedOptions().maximumFractionDigits;
  return formatter.format(minor / scale);
}
export function formatDate(iso) {
  const date = new Date(iso);
  if (Number.isNaN(date.getTime())) throw new TypeError('Invalid date');
  return new Intl.DateTimeFormat(current, { dateStyle: 'medium', timeStyle: 'short' }).format(date);
}
export function setLocale(code) {
  if (!languages.some(({ code: supported }) => supported === code)) return;
  current = code;
  document.documentElement.lang = code;
  try { localStorage.setItem('online-shopping-language', code); } catch { /* Optional. */ }
  translate(document);
  document.dispatchEvent(new CustomEvent('localechange'));
}

export function translate(root) {
  root.querySelectorAll('[data-i18n]').forEach((node) => { node.textContent = t(node.dataset.i18n); });
  root.querySelectorAll('[data-i18n-aria]').forEach((node) => { node.setAttribute('aria-label', t(node.dataset.i18nAria)); });
}

export function setupLanguageSelect(select) {
  for (const { code, label } of languages) {
    const option = document.createElement('option');
    option.value = code;
    option.textContent = label;
    select.append(option);
  }
  select.value = current;
  select.addEventListener('change', () => setLocale(select.value));
  setLocale(current);
}

export function setupLanguageMenu(host, { onOpen, showLabel = false } = {}) {
  const trigger = document.createElement('button');
  trigger.type = 'button';
  trigger.className = 'language-trigger';
  trigger.dataset.i18nAria = 'selectLanguage';
  trigger.setAttribute('aria-haspopup', 'true');
  trigger.setAttribute('aria-expanded', 'false');
  trigger.innerHTML = '<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="9"/><path d="M3 12h18M12 3c3 3 3 15 0 18M12 3c-3 3-3 15 0 18"/></svg>';
  let currentLabel;
  if (showLabel) {
    currentLabel = document.createElement('span'); currentLabel.className = 'utility-label language-current'; trigger.append(currentLabel);
    const chevron = document.createElementNS('http://www.w3.org/2000/svg', 'svg'); chevron.setAttribute('viewBox', '0 0 24 24'); chevron.setAttribute('aria-hidden', 'true'); chevron.classList.add('utility-chevron');
    const path = document.createElementNS('http://www.w3.org/2000/svg', 'path'); path.setAttribute('d', 'm6 9 6 6 6-6'); chevron.append(path); trigger.append(chevron);
  }
  const options = document.createElement('div');
  options.className = 'language-options';
  options.hidden = true;
  function close() { options.hidden = true; trigger.setAttribute('aria-expanded', 'false'); }
  for (const { code, label } of languages) {
    const option = document.createElement('button');
    option.type = 'button';
    option.textContent = label;
    option.lang = code;
    option.addEventListener('click', () => { setLocale(code); close(); trigger.focus(); });
    options.append(option);
  }
  function sync() {
    if (currentLabel) { currentLabel.textContent = languages.find(({ code }) => code === current).label; currentLabel.title = currentLabel.textContent; }
    trigger.setAttribute('aria-label', `${t('selectLanguage')}: ${languages.find(({ code }) => code === current).label}`);
    for (const option of options.children) option.setAttribute('aria-current', String(option.lang === current));
  }
  trigger.addEventListener('click', () => {
    if (onOpen) { trigger.setAttribute('aria-expanded', 'true'); onOpen(() => trigger.setAttribute('aria-expanded', 'false')); return; }
    options.hidden = !options.hidden;
    trigger.setAttribute('aria-expanded', String(!options.hidden));
    if (!options.hidden) options.querySelector('[aria-current="true"]').focus();
  });
  host.append(trigger, options);
  document.addEventListener('click', (event) => { if (!host.contains(event.target)) close(); });
  host.addEventListener('keydown', (event) => {
    if (event.key === 'Escape' && !options.hidden) { close(); trigger.focus(); }
  });
  document.addEventListener('localechange', sync);
  setLocale(current);
  sync();
}

